`timescale 1ns/1ps
// 64 deterministic vectors generated by the Python bit-exact reference.
module tb_fixedpoint_random;
  logic signed [3:0] previous_state, new_state, mixed_state;
  logic [3:0] beta_int;
  logic saturated;
  integer vector_index;
  `include "memory_mix_vectors.svh"
  relay_memory_mix #(.B(4), .M_SHIFT(3), .CLIP(7)) dut (.*);
  initial begin
    for (vector_index = 0; vector_index < MEMORY_MIX_VECTOR_COUNT; vector_index++) begin
      previous_state = memory_mix_prev(vector_index);
      new_state = memory_mix_new(vector_index);
      beta_int = memory_mix_beta(vector_index);
      #1;
      if (mixed_state !== memory_mix_expected(vector_index))
        $fatal(1, "vector %0d mismatch: got %0d expected %0d", vector_index, mixed_state, memory_mix_expected(vector_index));
    end
    $display("%0d Python-generated fixed-point vectors passed", MEMORY_MIX_VECTOR_COUNT);
    $finish;
  end
endmodule
